typedef uint16_t CssValueDef;

// The name of each production as the specs write it, as in "<bg-image>" or "counter()".
extern const PrStringView kCssValueDefName[CssValueDef_Count];

// The root of each production's grammar, an index into kCssGrammarNodes.
extern const CssGrammarIndex kCssValueDefGrammarRoot[CssValueDef_Count];

// Whether the production's components are written with no whitespace between them.
extern const uint64_t kCssValueDefNoWhitespace[bitsetWords(CssValueDef_Count)];

// Whether a structural match keeps a node for the production. A prose production keeps none, since its terminal is a
// value of its own. Nor does a production whose node would add nothing to its children's: one production, a choice of
// productions, or a run of one production that every reference takes as a whole grammar.
extern const uint64_t kCssValueDefKeepsNode[bitsetWords(CssValueDef_Count)];

// The math function that a function named `keyword` is (css-values-4/#math), or CssValueDef_Count if no math function
// has the name.
CssValueDef cssMathFunction(PrCssKeyword keyword);

// The <whole-value> function that a function named `keyword` is (css-values-5/#whole-value), or CssValueDef_Count if
// none has the name.
CssValueDef cssWholeValueFunction(PrCssKeyword keyword);

// The production that the arguments of the arbitrary substitution function named `keyword` must match before
// substitution (css-values-5/#arbitrary-substitution). CssValueDef_Count if no such function has the name.
CssValueDef cssSubstitutionFunction(PrCssKeyword keyword);

